mapper.select:
SELECT  FROM rule
WHERE workspace_id = #{workspaceId}
ORDER BY created_at DESC, id DESC

mapper.update:
UPDATE rule
SET name = #{name}, description = #{description}, enabled = #{enabled},
    record_type = #{recordType}, trigger_type = #{triggerType},
    trigger_config = #{triggerConfig}, condition_json = #{conditionJson},
    actions_json = #{actionsJson}, execution_mode = #{executionMode}, run_as_user_id = #{runAsUserId}
WHERE workspace_id = #{workspaceId} AND id = #{id}

mapper.select:
SELECT id, workspace_id, rule_id, trigger_entity_type, trigger_entity_id, status, dedupe_key, detail, executed_at
FROM rule_execution
WHERE workspace_id = #{workspaceId} AND rule_id = #{ruleId}
ORDER BY executed_at DESC, id DESC
LIMIT #{limit}
